1	package com.example.starter.race.service;
2	
3	import com.example.starter.race.api.AddPenaltyRequest;
4	import com.example.starter.race.api.CheckpointResponse;
5	import com.example.starter.race.api.CheckpointsConfigResponse;
6	import com.example.starter.race.api.ConfigureCheckpointsRequest;
7	import com.example.starter.race.api.CreateRaceRequest;
8	import com.example.starter.race.api.MissingCheckpointsResponse;
9	import com.example.starter.race.api.RaceResponse;
10	import com.example.starter.race.api.RegisterRunnerRequest;
11	import com.example.starter.race.api.ReviseTimeRequest;
12	import com.example.starter.race.api.RevokePenaltyRequest;
13	import com.example.starter.race.api.RunnerMissingCheckpointsResponse;
14	import com.example.starter.race.api.RunnerTimingResponse;
15	import com.example.starter.race.api.SealRaceRequest;
