21	import com.example.starter.race.domain.ResultCalculator;
22	import com.example.starter.race.domain.ResultEntry;
23	import com.example.starter.race.persistence.CheckpointRow;
24	import com.example.starter.race.persistence.CheckpointTimingRow;
25	import com.example.starter.race.persistence.IdempotencyRow;
26	import com.example.starter.race.persistence.PenaltyRow;
27	import com.example.starter.race.persistence.RaceRow;
28	import com.example.starter.race.persistence.RunnerRow;
29	import com.example.starter.race.persistence.SnapshotCheckpointRow;
30	import com.example.starter.race.persistence.SnapshotEntryRow;
31	import com.example.starter.race.persistence.SnapshotRow;
32	import com.example.starter.race.persistence.RaceRepository;
33	import com.fasterxml.jackson.databind.JsonNode;
34	import com.fasterxml.jackson.databind.ObjectMapper;
35	import org.springframework.dao.DuplicateKeyException;
36	import org.springframework.stereotype.Service;
37	import org.springframework.transaction.annotation.Transactional;
38	
39	import java.nio.charset.StandardCharsets;
40	import java.security.MessageDigest;
41	import java.security.NoSuchAlgorithmException;
42	import java.time.Clock;
43	import java.util.ArrayList;
44	import java.util.HexFormat;
45	import java.util.List;
46	import java.util.Map;
47	import java.util.Optional;
48	import java.util.TreeMap;
49	import java.util.function.Supplier;
50	
51	/**
52	 * {@link RaceService} 的事务实现。
53	 *
54	 * <p>并发与一致性要点：
55	 * <ul>
56	 *   <li>所有写操作先在 race 行上执行“状态=OPEN 且 version=expectedVersion”的条件 UPDATE，
57	 *       行锁串行化同赛事并发写，版本不匹配/已封榜均为0行并返回409，因此不会遗漏已先提交的变更；</li>
58	 *   <li>封榜在同一事务内完成条件转 SEALED 与全体选手只读快照写入；</li>
59	 *   <li>每个写请求以 requestId 唯一键先插入“进行中”占位行：同键并发阻塞至先行者事务结束；
60	 *       成功后在同一事务内补写原响应；业务失败随事务回滚，不占用 requestId 键；
61	 *       同键同参重放原成功结果，异参返回409。</li>
62	 * </ul>
63	 */
64	@Service
65	public class RaceServiceImpl implements RaceService {
66	
67	    /** 原始完赛耗时上界（毫秒），含端点：1天。 */
68	    private static final long MAX_FINISH_TIME_MS = 86_400_000L;
69	    /** 加时处罚上界（毫秒），含端点：1小时。 */
70	    private static final long MAX_PENALTY_MS = 3_600_000L;
71	    /** 同键并发时等待先行者事务结束的上限（毫秒）。 */
72	    private static final long INFLIGHT_WAIT_MAX_MS = 30_000L;
73	
74	    private final RaceRepository repository;
75	    private final Clock clock;
76	    private final ObjectMapper objectMapper;
77	
78	    public RaceServiceImpl(RaceRepository repository, Clock clock, ObjectMapper objectMapper) {
79	        this.repository = repository;
80	        this.clock = clock;
81	        this.objectMapper = objectMapper;
82	    }
83	
84	    @Override
85	    @Transactional
86	    public ServiceResult createRace(CreateRaceRequest request) {
87	        return withIdempotency(request.requestId(), "CREATE_RACE",
88	                orderedParams("raceId", request.raceId()),
89	                () -> {
90	                    long now = clock.millis();
91	                    try {
92	                        repository.insertRace(request.raceId(), now);
93	                    } catch (DuplicateKeyException ex) {
94	                        throw new ConflictException("赛事已存在: " + request.raceId());
95	                    }
96	                    RaceRow race = repository.findRace(request.raceId()).orElseThrow();
97	                    return ServiceResult.created(new RaceResponse(
98	                            race.raceId(), race.version(), race.status(), race.createdAt()));
99	                });
100	    }
101	
102	    @Override
103	    @Transactional
104	    public ServiceResult registerRunner(String raceId, RegisterRunnerRequest request) {
105	        return withIdempotency(request.requestId(), "REGISTER_RUNNER",
106	                orderedParams(
107	                        "raceId", raceId,
108	                        "bib", request.bib(),
109	                        "expectedVersion", request.expectedVersion(),
110	                        "finishTimeMs", request.finishTimeMs()),
111	                () -> {
112	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
113	                    Long finishTimeMs = request.finishTimeMs();
114	                    validateFinishTime(finishTimeMs, true);
115	                    long now = clock.millis();
116	                    bumpVersion(race, request.expectedVersion());
117	                    try {
118	                        repository.insertRunner(raceId, request.bib(), finishTimeMs, now);
119	                    } catch (DuplicateKeyException ex) {
120	                        throw new ConflictException("参赛号已存在: " + request.bib());
121	                    }
122	                    RunnerRow runner = repository.findRunner(raceId, request.bib()).orElseThrow();
123	                    return ServiceResult.created(ResponseMapper.toRunnerResponse(runner));
124	                });
125	    }
126	
127	    @Override
128	    @Transactional
129	    public ServiceResult reviseTime(String raceId, ReviseTimeRequest request) {
130	        return withIdempotency(request.requestId(), "REVISE_TIME",
131	                orderedParams(
132	                        "raceId", raceId,
133	                        "bib", request.bib(),
134	                        "expectedVersion", request.expectedVersion(),
135	                        "finishTimeMs", request.finishTimeMs()),
136	                () -> {
137	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
138	                    RunnerRow runner = requireRunner(raceId, request.bib());
139	                    validateFinishTime(request.finishTimeMs(), false);
140	                    // 修订后原始完赛耗时仍须严格大于该选手每一条已有分段耗时，否则分段不变量被破坏。
141	                    List<CheckpointTimingRow> runnerTimings =
142	                            repository.findTimingsForRunner(raceId, request.bib());
143	                    for (CheckpointTimingRow timing : runnerTimings) {
144	                        if (timing.elapsedMillis() >= request.finishTimeMs()) {
145	                            throw new UnprocessableEntityException(
146	                                    "修订后的完赛耗时必须严格大于已有分段耗时: "
147	                                            + timing.checkpointCode());
148	                        }
149	                    }
150	                    long now = clock.millis();
151	                    bumpVersion(race, request.expectedVersion());
152	                    int updated = repository.updateRunnerTiming(
153	                            raceId, request.bib(), request.finishTimeMs(), now);
154	                    if (updated == 0) {
155	                        throw new NotFoundException("选手不存在: " + request.bib());
156	                    }
157	                    RunnerRow refreshedRunner =
158	                            repository.findRunner(raceId, request.bib()).orElseThrow();
159	                    return ServiceResult.ok(ResponseMapper.toRunnerResponse(refreshedRunner));
160	                });
161	    }
162	
163	    @Override
164	    @Transactional
165	    public ServiceResult addPenalty(String raceId, AddPenaltyRequest request) {
166	        return withIdempotency(request.requestId(), "ADD_PENALTY",
167	                orderedParams(
168	                        "raceId", raceId,
169	                        "penaltyId", request.penaltyId(),
170	                        "bib", request.bib(),
171	                        "type", request.type(),
172	                        "amountMs", request.amountMs(),
173	                        "expectedVersion", request.expectedVersion()),
174	                () -> {
175	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
176	                    requireRunner(raceId, request.bib());
177	                    PenaltyType type = parsePenaltyType(request.type());
178	                    Long amountMs = request.amountMs();
179	                    if (type == PenaltyType.ADD_TIME) {
180	                        if (amountMs == null) {
181	                            throw new BadRequestException("加时处罚必须携带 amountMs");
182	                        }
183	                        if (amountMs < 1 || amountMs > MAX_PENALTY_MS) {
184	                            throw new BadRequestException("加时毫秒数必须在 1~3600000 之间");
185	                        }
186	                    } else if (amountMs != null) {
187	                        throw new BadRequestException("取消资格处罚不得携带 amountMs");
188	                    }
189	                    long now = clock.millis();
190	                    bumpVersion(race, request.expectedVersion());
191	                    try {
192	                        repository.insertPenalty(
193	                                request.penaltyId(), raceId, request.bib(), type, amountMs, now);
194	                    } catch (DuplicateKeyException ex) {
195	                        throw new ConflictException("处罚ID已存在: " + request.penaltyId());
196	                    }
197	                    PenaltyRow penalty = repository.findPenalty(request.penaltyId()).orElseThrow();
198	                    return ServiceResult.created(ResponseMapper.toPenaltyResponse(penalty));
199	                });
200	    }
201	
202	    @Override
203	    @Transactional
204	    public ServiceResult revokePenalty(
205	            String raceId, String penaltyId, RevokePenaltyRequest request) {
206	        return withIdempotency(request.requestId(), "REVOKE_PENALTY",
207	                orderedParams(
208	                        "raceId", raceId,
209	                        "penaltyId", penaltyId,
210	                        "expectedVersion", request.expectedVersion()),
211	                () -> {
212	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
213	                    PenaltyRow penalty = repository.findPenalty(penaltyId)
214	                            .orElseThrow(() -> new NotFoundException("处罚不存在: " + penaltyId));
215	                    if (!penalty.raceId().equals(raceId)) {
216	                        throw new NotFoundException("处罚不属于该赛事: " + penaltyId);
217	                    }
218	                    if (penalty.revoked()) {
219	                        throw new ConflictException("处罚已撤销: " + penaltyId);
220	                    }
221	                    long now = clock.millis();
222	                    bumpVersion(race, request.expectedVersion());
223	                    int updated = repository.markPenaltyRevoked(penaltyId, now);
224	                    if (updated == 0) {
225	                        throw new ConflictException("处罚已撤销: " + penaltyId);
226	                    }
227	                    PenaltyRow refreshed = repository.findPenalty(penaltyId).orElseThrow();
228	                    return ServiceResult.ok(ResponseMapper.toPenaltyResponse(refreshed));
229	                });
230	    }
231	
232	    @Override
233	    @Transactional
234	    public ServiceResult configureCheckpoints(String raceId, ConfigureCheckpointsRequest request) {
235	        List<ConfigureCheckpointsRequest.CheckpointDefinition> definitions =
236	                request.checkpoints().stream()
237	                        .sorted(java.util.Comparator
238	                                .comparingInt(ConfigureCheckpointsRequest.CheckpointDefinition::position)
239	                                .thenComparing(ConfigureCheckpointsRequest.CheckpointDefinition::checkpointCode))
240	                        .toList();
241	        return withIdempotency(request.requestId(), "CONFIGURE_CHECKPOINTS",
242	                orderedParams(
243	                        "raceId", raceId,
244	                        "expectedVersion", request.expectedVersion(),
245	                        "checkpoints", definitions.stream()
246	                                .map(def -> def.position() + ":" + def.checkpointCode())
247	                                .toList()),
248	                () -> {
249	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
250	                    validateCheckpointDefinitions(request.checkpoints());
251	                    if (!repository.findCheckpoints(raceId).isEmpty()) {
252	                        throw new ConflictException("赛事已配置检查点，配置后不可修改: " + raceId);
253	                    }
254	                    if (repository.countTimings(raceId) > 0) {
255	                        throw new ConflictException("赛事已存在分段记录，不能再配置检查点: " + raceId);
256	                    }
257	                    bumpVersion(race, request.expectedVersion());
258	                    long now = clock.millis();
259	                    List<CheckpointRow> rows = request.checkpoints().stream()
260	                            .map(def -> new CheckpointRow(
261	                                    raceId, def.checkpointCode(), def.position(), now))
262	                            .toList();
263	                    repository.insertCheckpoints(rows);
264	                    List<CheckpointResponse> responses = repository.findCheckpoints(raceId).stream()
265	                            .map(row -> new CheckpointResponse(row.checkpointCode(), row.position()))
266	                            .toList();
267	                    return ServiceResult.created(new CheckpointsConfigResponse(
268	                            raceId, request.expectedVersion() + 1, responses));
269	                });
270	    }
271	
272	    @Override
273	    @Transactional
274	    public ServiceResult submitTiming(String raceId, String bib, SubmitTimingRequest request) {
275	        return withIdempotency(request.requestId(), "SUBMIT_TIMING",
276	                orderedParams(
277	                        "raceId", raceId,
278	                        "bib", bib,
279	                        "timingId", request.timingId(),
280	                        "checkpointCode", request.checkpointCode(),
281	                        "elapsedMillis", request.elapsedMillis(),
282	                        "expectedVersion", request.expectedVersion()),
283	                () -> {
284	                    // timingId 是第二层全局幂等键：同参重放原结果，异参409。
285	                    CheckpointTimingRow existingTiming =
286	                            repository.findTiming(request.timingId()).orElse(null);
287	                    if (existingTiming != null) {
288	                        return replayTimingOrConflict(raceId, bib, request, existingTiming);
289	                    }
290	
291	                    RaceRow race = requireOpenRace(raceId, request.expectedVersion());
292	                    RunnerRow runner = requireRunner(raceId, bib);
293	                    CheckpointRow checkpoint = repository
294	                            .findCheckpoint(raceId, request.checkpointCode())
295	                            .orElseThrow(() -> new NotFoundException(
296	                                    "检查点不存在: " + request.checkpointCode()));
297	                    long elapsedMillis = request.elapsedMillis();
298	                    List<CheckpointTimingRow> runnerTimings =
299	                            repository.findTimingsForRunner(raceId, bib);
300	                    String violation = CheckpointRules.validate(
301	                            runnerTimings, checkpoint.position(), elapsedMillis,
302	                            runner.finishTimeMs());
303	                    if (violation != null) {
304	                        throw new UnprocessableEntityException(violation);
305	                    }
306	                    bumpVersion(race, request.expectedVersion());
307	                    long now = clock.millis();
308	                    CheckpointTimingRow row = new CheckpointTimingRow(
309	                            request.timingId(), raceId, bib, request.checkpointCode(),
310	                            checkpoint.position(), elapsedMillis, now);
311	                    try {
312	                        repository.insertTiming(row);
313	                    } catch (DuplicateKeyException ex) {
314	                        // 并发下唯一约束兜底：同 timingId 走重放/异参冲突，其余为分段重复。
315	                        if (constraintMatches(ex, "pk_checkpoint_timing")) {
316	                            CheckpointTimingRow concurrent =
317	                                    repository.findTiming(request.timingId()).orElseThrow();
318	                            return replayTimingOrConflict(raceId, bib, request, concurrent);
319	                        }
320	                        throw new UnprocessableEntityException(
321	                                "同一选手同一检查点最多一条分段记录");
322	                    }
323	                    CheckpointTimingRow saved =
324	                            repository.findTiming(request.timingId()).orElseThrow();
325	                    return ServiceResult.created(ResponseMapper.toTimingResponse(saved));
326	                });
327	    }
328	
329	    private ServiceResult replayTimingOrConflict(
330	            String raceId,
331	            String bib,
332	            SubmitTimingRequest request,
333	            CheckpointTimingRow existing) {
334	        boolean sameParams = existing.raceId().equals(raceId)
335	                && existing.bib().equals(bib)
336	                && existing.checkpointCode().equals(request.checkpointCode())
337	                && existing.elapsedMillis() == request.elapsedMillis();
338	        if (!sameParams) {
339	            throw new ConflictException(
340	                    "timingId 已用于不同参数的分段记录: " + request.timingId());
341	        }
342	        return ServiceResult.created(ResponseMapper.toTimingResponse(existing));
343	    }
344	
345	    @Override
346	    @Transactional
347	    public ServiceResult sealRace(String raceId, SealRaceRequest request) {
348	        return withIdempotency(request.requestId(), "SEAL_RACE",
349	                orderedParams(
350	                        "raceId", raceId,
351	                        "expectedVersion", request.expectedVersion()),
352	                () -> {
353	                    RaceRow race = repository.findRaceForUpdate(raceId)
354	                            .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
355	                    if (race.status() == RaceStatus.SEALED) {
356	                        throw new ConflictException("赛事已封榜: " + raceId);
357	                    }
358	                    List<RunnerRow> runners = repository.findRunners(raceId);
359	                    List<PenaltyRow> penalties = repository.findPenalties(raceId);
360	                    List<CheckpointRow> checkpoints = repository.findCheckpoints(raceId);
361	                    List<CheckpointTimingRow> timings = repository.findAllTimings(raceId);
362	                    List<ResultEntry> entries =
363	                            ResultCalculator.compute(runners, penalties, checkpoints, timings);
364	
365	                    int newVersion = request.expectedVersion() + 1;
366	                    int updated = repository.sealIfOpenAtVersion(
367	                            raceId, request.expectedVersion(), newVersion);
368	                    if (updated == 0) {
369	                        throw new ConflictException("版本冲突或赛事已封榜");
370	                    }
371	                    long now = clock.millis();
372	                    List<SnapshotEntryRow> snapshotEntries = new ArrayList<>(entries.size());
373	                    for (int order = 0; order < entries.size(); order++) {
374	                        ResultEntry entry = entries.get(order);
375	                        snapshotEntries.add(new SnapshotEntryRow(
376	                                raceId,
377	                                entry.bib(),
378	                                entry.rank(),
379	                                entry.status(),
380	                                entry.finishTimeMs(),
381	                                entry.penaltyMs(),
382	                                entry.totalTimeMs(),
383	                                order,
384	                                entry.checkpointCount(),
385	                                entry.coveredCheckpointCount(),
386	                                entry.missingCheckpoints()));
387	                    }
388	                    // 在同一封榜事务内固化每名选手 × 每个检查点的明细，缺失行耗时为 null。
389	                    List<SnapshotCheckpointRow> snapshotCheckpoints =
390	                            buildSnapshotCheckpoints(raceId, runners, checkpoints, timings);
391	                    repository.insertSnapshot(new SnapshotRow(raceId, newVersion, now,
392	                            snapshotEntries, snapshotCheckpoints));
393	                    return ServiceResult.ok(new StandingResponse(
394	                            raceId, newVersion, RaceStatus.SEALED, now,
395	                            snapshotEntries.stream().map(ResponseMapper::toEntryResponse).toList()));
396	                });
397	    }
398	
399	    @Override
400	    @Transactional(readOnly = true)
401	    public StandingResponse getResults(String raceId) {
402	        RaceRow race = repository.findRace(raceId)
403	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
404	        if (race.status() == RaceStatus.SEALED) {
405	            SnapshotRow snapshot = repository.findSnapshot(raceId)
406	                    .orElseThrow(() -> new IllegalStateException(
407	                            "赛事已封榜但缺少快照: " + raceId));
408	            return ResponseMapper.snapshotStanding(snapshot);
409	        }
410	        return ResponseMapper.liveStanding(
411	                race,
412	                repository.findRunners(raceId),
413	                repository.findPenalties(raceId),
414	                repository.findCheckpoints(raceId),
415	                repository.findAllTimings(raceId));
416	    }
417	
418	    @Override
419	    @Transactional(readOnly = true)
420	    public RunnerTimingResponse getRunnerTimings(String raceId, String bib) {
421	        RaceRow race = repository.findRace(raceId)
422	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
423	        RunnerRow runner = repository.findRunner(raceId, bib)
424	                .orElseThrow(() -> new NotFoundException("选手不存在: " + bib));
425	        List<CheckpointRow> checkpoints = repository.findCheckpoints(raceId);
426	        if (race.status() == RaceStatus.SEALED) {
427	            SnapshotRow snapshot = repository.findSnapshot(raceId)
428	                    .orElseThrow(() -> new IllegalStateException(
429	                            "赛事已封榜但缺少快照: " + raceId));
430	            return ResponseMapper.snapshotRunnerTiming(
431	                    snapshot, bib, runner.finishTimeMs(), checkpoints);
432	        }
433	        return ResponseMapper.runnerTiming(
434	                race, runner, checkpoints, repository.findTimingsForRunner(raceId, bib));
435	    }
436	
437	    @Override
438	    @Transactional(readOnly = true)
439	    public MissingCheckpointsResponse getMissingCheckpoints(String raceId) {
440	        RaceRow race = repository.findRace(raceId)
441	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
442	        List<CheckpointRow> checkpoints = repository.findCheckpoints(raceId);
443	        List<RunnerRow> runners;
444	        List<CheckpointTimingRow> timings;
445	        if (race.status() == RaceStatus.SEALED) {
446	            SnapshotRow snapshot = repository.findSnapshot(raceId)
447	                    .orElseThrow(() -> new IllegalStateException(
448	                            "赛事已封榜但缺少快照: " + raceId));
449	            // 封榜后由固化明细派生缺失检查点，缺失行 elapsedMillis 为 null。
450	            Map<String, List<String>> missingByBib = new TreeMap<>();
451	            for (SnapshotCheckpointRow detail : snapshot.checkpoints()) {
452	                if (detail.elapsedMillis() == null) {
453	                    missingByBib.computeIfAbsent(detail.bib(), key -> new ArrayList<>())
454	                            .add(detail.checkpointCode());
455	                }
456	            }
457	            List<RunnerRow> sealedRunners = repository.findRunners(raceId);
458	            List<RunnerMissingCheckpointsResponse> rows = sealedRunners.stream()
459	                    .map(runner -> new RunnerMissingCheckpointsResponse(
460	                            runner.bib(),
461	                            missingByBib.getOrDefault(runner.bib(), List.of())))
462	                    .toList();
463	            return new MissingCheckpointsResponse(
464	                    raceId, race.version(), checkpoints.size(), rows);
465	        }
466	        runners = repository.findRunners(raceId);
467	        timings = repository.findAllTimings(raceId);
468	        // 按参赛号字典序稳定汇总；缺失=已配置但该选手尚无分段记录的检查点。
469	        Map<String, java.util.Set<String>> coveredByBib = new TreeMap<>();
470	        for (RunnerRow runner : runners) {
471	            coveredByBib.put(runner.bib(), new java.util.HashSet<>());
472	        }
473	        for (CheckpointTimingRow timing : timings) {
474	            java.util.Set<String> covered = coveredByBib.get(timing.bib());
475	            if (covered != null) {
476	                covered.add(timing.checkpointCode());
477	            }
478	        }
479	        List<RunnerMissingCheckpointsResponse> rows = coveredByBib.entrySet().stream()
480	                .map(entry -> new RunnerMissingCheckpointsResponse(
481	                        entry.getKey(),
482	                        checkpoints.stream()
483	                                .map(CheckpointRow::checkpointCode)
484	                                .filter(code -> !entry.getValue().contains(code))
485	                                .toList()))
486	                .toList();
487	        return new MissingCheckpointsResponse(
488	                raceId, race.version(), checkpoints.size(), rows);
489	    }
490	
491	    @Override
492	    @Transactional(readOnly = true)
493	    public StandingResponse getSnapshot(String raceId) {
494	        repository.findRace(raceId)
495	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
496	        SnapshotRow snapshot = repository.findSnapshot(raceId)
497	                .orElseThrow(() -> new NotFoundException("赛事尚未封榜: " + raceId));
498	        return ResponseMapper.snapshotStanding(snapshot);
499	    }
500	
501	    /**
502	     * 幂等包装：同键同参重放原成功结果，同键异参409；
503	     * 业务异常随事务回滚，占位行消失，不占用 requestId。
504	     */
505	    private ServiceResult withIdempotency(
506	            String requestId,
507	            String operation,
508	            TreeMap<String, Object> params,
509	            Supplier<ServiceResult> action) {
510	        String digest = digest(operation, params);
511	        long deadline = clock.millis() + INFLIGHT_WAIT_MAX_MS;
512	        boolean acquired = false;
513	        while (!acquired) {
514	            try {
515	                repository.insertIdempotencyPlaceholder(
516	                        requestId, operation, digest, clock.millis());
517	                acquired = true;
518	            } catch (DuplicateKeyException ex) {
519	                Optional<IdempotencyRow> existing =
520	                        repository.findIdempotencyForUpdate(requestId);
521	                if (existing.isEmpty()) {
522	                    // 先行者事务回滚，占位行已随其消失，立即重新占位。
523	                    continue;
524	                }
525	                IdempotencyRow row = existing.get();
526	                if (row.responseStatus() == 0) {
527	                    // 理论上不会出现（提交必带最终响应）；防御性等待先行者完成。
528	                    if (clock.millis() >= deadline) {
529	                        throw new ConflictException("相同 requestId 的请求仍在处理中");
530	                    }
531	                    sleepBriefly();
532	                    continue;
533	                }
534	                if (!row.requestDigest().equals(digest)) {
535	                    throw new ConflictException(
536	                            "requestId 已用于不同参数的请求: " + requestId);
537	                }
538	                JsonNode replayedBody = parseReplayedBody(row.responseBody());
539	                return new ServiceResult(replayedBody, row.responseStatus());
540	            }
541	        }
542	        ServiceResult result = action.get();
543	        repository.completeIdempotency(
544	                requestId, result.status(), writeJson(result.body()));
545	        return result;
546	    }
547	
548	    private RaceRow requireOpenRace(String raceId, Integer expectedVersion) {
549	        // 先取 race 行写锁并持有到事务结束：本事务随后读到的选手/处罚/分段数据
550	        // 必然处于某个已串行化的赛事版本上，不会与并发写者的已提交明细交错。
551	        RaceRow race = repository.findRaceForUpdate(raceId)
552	                .orElseThrow(() -> new NotFoundException("赛事不存在: " + raceId));
553	        if (race.status() == RaceStatus.SEALED) {
554	            throw new ConflictException("赛事已封榜，禁止写入: " + raceId);
555	        }
556	        if (race.version() != expectedVersion) {
557	            throw new ConflictException("版本冲突: expected=" + expectedVersion
558	                    + ", actual=" + race.version());
559	        }
560	        return race;
561	    }
562	
563	    private void bumpVersion(RaceRow race, int expectedVersion) {
564	        int updated = repository.bumpVersionIfOpen(race.raceId(), expectedVersion);
565	        if (updated == 0) {
566	            // 行锁释放后发现赛事已封榜或版本已被推进。
567	            RaceRow refreshed = repository.findRace(race.raceId()).orElseThrow();
568	            if (refreshed.status() == RaceStatus.SEALED) {
569	                throw new ConflictException("赛事已封榜，禁止写入: " + race.raceId());
570	            }
571	            throw new ConflictException("版本冲突: expected=" + expectedVersion
572	                    + ", actual=" + refreshed.version());
573	        }
574	    }
575	
576	    private RunnerRow requireRunner(String raceId, String bib) {
577	        return repository.findRunner(raceId, bib)
578	                .orElseThrow(() -> new NotFoundException("选手不存在: " + bib));
579	    }
580	
581	    private static void validateFinishTime(Long finishTimeMs, boolean nullable) {
582	        if (finishTimeMs == null) {
583	            if (!nullable) {
584	                throw new BadRequestException("修订计时必须携带 finishTimeMs");
585	            }
586	            return;
587	        }
588	        if (finishTimeMs < 1 || finishTimeMs > MAX_FINISH_TIME_MS) {
589	            throw new BadRequestException("完赛耗时毫秒数必须在 1~86400000 之间");
590	        }
591	    }
592	
593	    private static PenaltyType parsePenaltyType(String type) {
594	        try {
595	            return PenaltyType.valueOf(type);
596	        } catch (IllegalArgumentException ex) {
597	            throw new BadRequestException("未知处罚类型: " + type);
598	        }
599	    }
600	
601	    private static TreeMap<String, Object> orderedParams(Object... keyValues) {
602	        if (keyValues.length % 2 != 0) {
603	            throw new IllegalArgumentException("参数必须为键值对");
604	        }
605	        TreeMap<String, Object> params = new TreeMap<>();
606	        for (int i = 0; i < keyValues.length; i += 2) {
607	            params.put((String) keyValues[i], keyValues[i + 1]);
608	        }
609	        return params;
610	    }
611	
612	    private String digest(String operation, Map<String, Object> params) {
613	        try {
614	            Map<String, Object> canonical = new TreeMap<>(params);
615	            canonical.put("__operation", operation);
616	            MessageDigest messageDigest = MessageDigest.getInstance("SHA-256");
617	            byte[] bytes = objectMapper.writerWithDefaultPrettyPrinter()
618	                    .writeValueAsString(canonical)
619	                    .getBytes(StandardCharsets.UTF_8);
620	            return HexFormat.of().formatHex(messageDigest.digest(bytes));
621	        } catch (NoSuchAlgorithmException | com.fasterxml.jackson.core.JsonProcessingException ex) {
622	            throw new IllegalStateException("计算请求摘要失败", ex);
623	        }
624	    }
625	
626	    private String writeJson(Object body) {
627	        try {
628	            return objectMapper.writeValueAsString(body);
629	        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
630	            throw new IllegalStateException("序列化响应失败", ex);
631	        }
632	    }
633	
634	    private JsonNode parseReplayedBody(String body) {
635	        try {
636	            return objectMapper.readTree(body);
637	        } catch (com.fasterxml.jackson.core.JsonProcessingException ex) {
638	            throw new IllegalStateException("解析原响应失败", ex);
639	        }
640	    }
641	
642	    private static void sleepBriefly() {
643	        try {
644	            Thread.sleep(10L);
645	        } catch (InterruptedException ex) {
646	            Thread.currentThread().interrupt();
647	            throw new ConflictException("等待同键请求完成时被中断");
648	        }
649	    }
650	
651	    /**
652	     * 校验检查点配置请求体：1~20个、代码非空且赛事内唯一、position 从1连续递增（无重复无缺口）。
653	     */
654	    private static void validateCheckpointDefinitions(
655	            List<ConfigureCheckpointsRequest.CheckpointDefinition> definitions) {
656	        if (definitions.isEmpty() || definitions.size() > 20) {
657	            throw new BadRequestException("检查点数量必须在 1~20 之间");
658	        }
659	        java.util.Set<String> codes = new java.util.HashSet<>();
660	        java.util.Set<Integer> positions = new java.util.HashSet<>();
661	        for (ConfigureCheckpointsRequest.CheckpointDefinition def : definitions) {
662	            if (!codes.add(def.checkpointCode())) {
663	                throw new BadRequestException("检查点代码在赛事内重复: " + def.checkpointCode());
664	            }
665	            positions.add(def.position());
666	        }
667	        for (int expected = 1; expected <= definitions.size(); expected++) {
668	            if (!positions.contains(expected)) {
669	                throw new BadRequestException(
670	                        "检查点顺序必须从1连续递增，缺少 position=" + expected);
671	            }
672	        }
673	    }
674	
675	    /**
676	     * 构造封榜快照的全部分段明细：每名选手 × 每个检查点一行，
677	     * 已有通过记录固化耗时与 timingId，缺失检查点对应字段为 null；顺序为参赛号、检查点顺序。
678	     */
679	    private List<SnapshotCheckpointRow> buildSnapshotCheckpoints(
680	            String raceId,
681	            List<RunnerRow> runners,
682	            List<CheckpointRow> checkpoints,
683	            List<CheckpointTimingRow> timings) {
684	        Map<String, Map<String, CheckpointTimingRow>> byBibAndCode = new TreeMap<>();
685	        for (CheckpointTimingRow timing : timings) {
686	            byBibAndCode
687	                    .computeIfAbsent(timing.bib(), key -> new TreeMap<>())
688	                    .put(timing.checkpointCode(), timing);
689	        }
690	        List<SnapshotCheckpointRow> rows = new ArrayList<>();
691	        // runners 已按参赛号字典序返回，保证无分段记录的选手也被完整固化为“全部缺失”。
692	        for (RunnerRow runner : runners) {
693	            appendSnapshotCheckpointRows(
694	                    rows, raceId, runner.bib(), checkpoints,
695	                    byBibAndCode.getOrDefault(runner.bib(), Map.of()));
696	        }
697	        return rows;
698	    }
699	
700	    private void appendSnapshotCheckpointRows(
701	            List<SnapshotCheckpointRow> rows,
702	            String raceId,
703	            String bib,
704	            List<CheckpointRow> checkpoints,
705	            Map<String, CheckpointTimingRow> timingByCode) {
706	        for (CheckpointRow checkpoint : checkpoints) {
707	            CheckpointTimingRow timing = timingByCode.get(checkpoint.checkpointCode());
708	            if (timing == null) {
709	                rows.add(new SnapshotCheckpointRow(
710	                        raceId, bib, checkpoint.checkpointCode(),
711	                        checkpoint.position(), null, null));
712	            } else {
713	                rows.add(new SnapshotCheckpointRow(
714	                        raceId, bib, checkpoint.checkpointCode(),
715	                        checkpoint.position(), timing.elapsedMillis(), timing.timingId()));
716	            }
717	        }
718	    }
719	
720	    /** 判断唯一约束异常是否源自指定约束（H2 异常信息中的约束名可能为大写）。 */
721	    private static boolean constraintMatches(DuplicateKeyException ex, String constraintName) {
722	        Throwable cause = ex.getMostSpecificCause();
723	        String message = cause.getMessage();
724	        return message != null
725	                && message.toUpperCase(java.util.Locale.ROOT).contains(constraintName.toUpperCase(java.util.Locale.ROOT));
726	    }
727	}
