13	/**
14	 * 赛事计时处罚与成绩封榜 HTTP 接口。
15	 */
16	@RestController
17	@RequestMapping("/api/races")
18	public class RaceController {
19	
20	    private final RaceService raceService;
21	
22	    public RaceController(RaceService raceService) {
23	        this.raceService = raceService;
24	    }
25	
26	    /** 新建赛事。 */
