38	    }
39	
40	    /** 计时修订。 */
41	    @PostMapping("/{raceId}/timing-revisions")
42	    public ResponseEntity<Object> reviseTime(
43	            @PathVariable String raceId,
44	            @Valid @RequestBody ReviseTimeRequest request) {
45	        return toResponse(raceService.reviseTime(raceId, request));
46	    }
47	
48	    /** 新增处罚。 */
49	    @PostMapping("/{raceId}/penalties")
