1	package com.example.starter.race.domain;
2	
3	import java.util.ArrayList;
4	import java.util.Comparator;
5	import java.util.HashSet;
6	import java.util.LinkedHashMap;
7	import java.util.List;
8	import java.util.Map;
9	import java.util.Set;
10	
11	/**
12	 * 成绩排名纯逻辑：依据选手原始耗时、处罚列表与检查点覆盖情况计算榜单，
13	 * 不涉及数据库与时间。
14	 *
15	 * <p>规则：
16	 * <ul>
17	 *   <li>总耗时=原始完赛耗时+全部未撤销 ADD_TIME 加时之和；</li>
18	 *   <li>存在未撤销 DISQUALIFY 处罚时状态 DISQUALIFIED，不排名，全部撤销后恢复计算；</li>
19	 *   <li>原始耗时缺失（null）时状态 UNTIMED，不排名；</li>
20	 *   <li>赛事配置了检查点时：已有完赛耗时但未覆盖全部检查点的选手状态
21	 *       MISSING_CHECKPOINT，不排名；全部覆盖后恢复加时与并列排名规则；
22	 *       未配置检查点的赛事沿用原排名规则；</li>
23	 *   <li>正常选手按总耗时升序，同耗时同名次，下一名次跳过并列人数（1、1、3）；</li>
24	 *   <li>并列者及未排名者内部均按参赛号字典序展示。</li>
25	 * </ul>
26	 */
27	public final class ResultCalculator {
28	
29	    private ResultCalculator() {
30	    }
31	
32	    /** 未配置检查点的赛事使用的兼容入口：无检查点、无分段记录。 */
33	    public static List<ResultEntry> compute(
34	            List<? extends RunnerView> runnerView,
35	            List<? extends PenaltyView> penalties) {
36	        return compute(runnerView, penalties, List.of(), List.of());
37	    }
38	
39	    /**
40	     * 计算即时成绩。
41	     *
42	     * @param runnerView  全部选手视图（参赛号、原始完赛耗时）
43	     * @param penalties   全部处罚（含已撤销）
44	     * @param checkpoints 赛事检查点配置（按 position 排序后使用）；为空表示赛事未配置检查点
45	     * @param timings     全部选手的分段通过记录
46	     * @return 按展示顺序排列的成绩条目
47	     */
48	    public static List<ResultEntry> compute(
49	            List<? extends RunnerView> runnerView,
50	            List<? extends PenaltyView> penalties,
51	            List<? extends CheckpointView> checkpoints,
52	            List<? extends TimingView> timings) {
53	        List<CheckpointView> orderedCheckpoints = new ArrayList<>(checkpoints);
54	        orderedCheckpoints.sort(Comparator.comparingInt(CheckpointView::position)
55	                .thenComparing(CheckpointView::checkpointCode));
56	        int checkpointCount = orderedCheckpoints.size();
57	
58	        Map<String, Aggregate> aggregates = new LinkedHashMap<>();
59	        for (RunnerView runner : runnerView) {
60	            aggregates.put(runner.bib(),
61	                    new Aggregate(runner.bib(), runner.finishTimeMs(), orderedCheckpoints));
62	        }
63	
64	        // 仅统计属于已配置检查点的分段（数据库外键已保证，这里做防御性过滤）。
65	        Set<String> configuredCodes = new HashSet<>();
66	        for (CheckpointView checkpoint : orderedCheckpoints) {
67	            configuredCodes.add(checkpoint.checkpointCode());
68	        }
69	        for (TimingView timing : timings) {
70	            Aggregate aggregate = aggregates.get(timing.bib());
71	            if (aggregate == null || !configuredCodes.contains(timing.checkpointCode())) {
72	                continue;
73	            }
74	            aggregate.coveredCodes.add(timing.checkpointCode());
75	        }
76	
77	        for (PenaltyView penalty : penalties) {
78	            Aggregate aggregate = aggregates.get(penalty.bib());
79	            if (aggregate == null || penalty.revoked()) {
80	                continue;
81	            }
82	            if (penalty.type() == PenaltyType.DISQUALIFY) {
83	                aggregate.disqualified = true;
84	            } else if (penalty.type() == PenaltyType.ADD_TIME && penalty.amountMs() != null) {
85	                aggregate.penaltyMs += penalty.amountMs();
86	            }
87	        }
88	
89	        List<Aggregate> ranked = new ArrayList<>();
90	        List<Aggregate> others = new ArrayList<>();
91	        for (Aggregate aggregate : aggregates.values()) {
92	            if (aggregate.disqualified) {
93	                aggregate.status = EntryStatus.DISQUALIFIED;
94	                others.add(aggregate);
95	            } else if (aggregate.finishTimeMs == null) {
96	                aggregate.status = EntryStatus.UNTIMED;
97	                others.add(aggregate);
98	            } else if (checkpointCount > 0 && aggregate.coveredCodes.size() < checkpointCount) {
99	                aggregate.status = EntryStatus.MISSING_CHECKPOINT;
100	                others.add(aggregate);
101	            } else {
102	                aggregate.status = EntryStatus.RANKED;
103	                aggregate.totalTimeMs = aggregate.finishTimeMs + aggregate.penaltyMs;
104	                ranked.add(aggregate);
105	            }
106	        }
107	
108	        ranked.sort(Comparator
109	                .comparingLong((Aggregate a) -> a.totalTimeMs)
110	                .thenComparing(a -> a.bib));
111	        others.sort(Comparator.comparing(a -> a.bib));
112	
113	        int index = 0;
114	        while (index < ranked.size()) {
115	            int groupEnd = index + 1;
