                    + "(penalty_id, race_id, bib, type, amount_ms, category_code, revoked, created_at, revoked_at) "
                    + "VALUES (?, ?, ?, ?, ?, ?, FALSE, ?, NULL)",
            penaltyId, raceId, bib, type.name(), amountMs, categoryCode, now);
}
